const DB_FILE = path.join(__dirname, 'runtime_db.json');

function buildInitialDb() {
  const subs = Array.isArray(RAW_SUBJECTS_RAW) ? RAW_SUBJECTS_RAW : (RAW_SUBJECTS_RAW.subjects || []);
  return {
    schemaVersion: 'STRICT_REALTIME_V3',
    rosterMode: 'CLASS_93',
    activeDayOfWeek: 2,
    className: 'Lớp 9/3 (43 Học sinh)',
    students: RAW_STUDENTS.map((s, idx) => ({
      id: idx + 1,
      stt: Number(s.stt),
      student_id: String(s.student_id || '').trim(),
      full_name: String(s.full_name || '').trim(),
      role: String(s.role || 'STUDENT').trim(),
      xp: 0,
      streak: 0,
      badges: []
    })),
    teachers: subs.map((sub, idx) => ({
      id: idx + 1,
      subject_code: String(sub.subject_code || '').trim(),
      subject_name: String(sub.subject_name || '').trim(),
      teacher_name: sub.teacher_name || (sub.is_homeroom ? 'Cô Nguyễn Thị Tố Trinh (GVCN)' : 'GVBM ' + sub.subject_name),
      is_homeroom: Boolean(sub.is_homeroom)
    })),
    timetable: RAW_TIMETABLE,
    keywordAliases: RAW_SUBJECTS_RAW.keyword_aliases || {},
    assignments: [],
    submissions: [],
    notification_logs: []
  };
}
function loadDb() {
  try {
    if (fs.existsSync(DB_FILE)) {
      const parsed = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
      if (parsed && parsed.schemaVersion === 'STRICT_REALTIME_V3') return parsed;
    }
  } catch (e) {}
  const fresh = buildInitialDb();
  saveDb(fresh);
  return fresh;
}
function saveDb(state) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(state, null, 2), 'utf-8');
  } catch (e) {}
}
function resetDb() {
  const fresh = buildInitialDb();
  saveDb(fresh);
  return fresh;
}
function switchRosterMode() {
  return loadDb();
}
function getMergedScheduleForDay(timetable, dayOfWeek = 2) {
  const slots = timetable.period_slots || [];
  const dayEntries = (timetable.weekly_schedule || [])
    .filter((item) => Number(item.day_of_week) === Number(dayOfWeek))
    .sort((a, b) => a.period - b.period);
  const mergedMap = new Map();
  dayEntries.forEach((entry) => {
    const slotInfo = slots.find((s) => Number(s.period) === entry.period) || {
      start: '07:00',
      end: '07:45',
      cutoff: '06:30'
    };
    if (!mergedMap.has(entry.subject_code)) {
      mergedMap.set(entry.subject_code, {
        day_of_week: Number(dayOfWeek),
        subject_code: entry.subject_code,
        periods: [entry.period],
        start_time: slotInfo.start,
        end_time: slotInfo.end,
        cutoff_time: slotInfo.cutoff
      });
    } else {
      const ex = mergedMap.get(entry.subject_code);
      ex.periods.push(entry.period);
      ex.end_time = slotInfo.end;
    }
  });
  return Array.from(mergedMap.values()).map((item) => ({
    ...item,
    periods_merged: item.periods.length > 1 ? item.periods[0] + '–' + item.periods[item.periods.length - 1] : String(item.periods[0]),
    periods_label: item.periods.length > 1 ? 'Tiết ' + item.periods[0] + '–' + item.periods[item.periods.length - 1] : 'Tiết ' + item.periods[0]
  }));
}
