function executeCutoffForAssignment({ assignmentId, dayOfWeek, period }, io) {
  const db = loadDb();

  let assignment = null;
  if (assignmentId) {
    assignment = db.assignments.find((a) => a.id === assignmentId);
  }

  if (!assignment && dayOfWeek && period) {
    db.activeDayOfWeek = Number(dayOfWeek);
    const schedEntry = (db.timetable.weekly_schedule || []).find(
      (s) =>
        Number(s.day_of_week) === Number(dayOfWeek) &&
        Number(s.period) === Number(period)
    );

    if (schedEntry) {
      assignment = db.assignments.find(
        (a) =>
          Number(a.day_of_week) === Number(dayOfWeek) &&
          String(a.subject_code).trim() === String(schedEntry.subject_code).trim()
      );
    }

    if (!assignment) {
      assignment = db.assignments.find(
        (a) => Number(a.day_of_week) === Number(dayOfWeek)
      );
    }
  }

  if (!assignment) {
    return null;
  }

  // Chuyển trạng thái bài tập sang "Đã khóa sổ"
  assignment.is_locked = true;

  const teacher = db.teachers.find((t) => t.subject_code === assignment.subject_code);
  const monitors = db.students.filter(
    (s) => s.role === 'MONITOR_LEADER' || s.role === 'MONITOR_VICE'
  );

  let completedCount = 0;
  let incompleteCount = 0;
  let unsubmittedCount = 0;
  const missingStudentNames = [];
  const incompleteStudentNames = [];

  db.students.forEach((student) => {
    const sub = db.submissions.find(
      (s) => s.assignment_id === assignment.id && Number(s.student_id) === Number(student.id)
    );
    if (!sub || sub.status === 'INVALID_IMAGE') {
      unsubmittedCount++;
      missingStudentNames.push(`${String(student.stt).padStart(2, '0')}. ${student.full_name}`);
    } else if (sub.status === 'INCOMPLETE') {
      incompleteCount++;
      incompleteStudentNames.push(
        `${String(student.stt).padStart(2, '0')}. ${student.full_name} (Thiếu: ${(
          sub.missing_items || []
        ).join(', ')})`
      );
    } else if (sub.status === 'COMPLETED') {
      completedCount++;
    }
  });

  const recipients = [
    teacher ? `${teacher.teacher_name} (${teacher.subject_name})` : assignment.subject_code,
    'Cô Nguyễn Thị Tố Trinh (GVCN)',
    ...monitors.map(
      (m) =>
        `${m.full_name} (${m.role === 'MONITOR_LEADER' ? 'Lớp trưởng' : 'Lớp phó HT'})`
    )
  ];

  const subjectName = teacher ? teacher.subject_name : assignment.subject_code;
  const totalStudents = db.students.length;
  const dayLabel = `Thứ ${assignment.day_of_week || 2}`;

  const notificationRecord = {
    id: 'NOTIF_' + Date.now(),
    assignment_id: assignment.id,
    day_of_week: assignment.day_of_week || 2,
    subject_code: assignment.subject_code,
    subject_name: subjectName,
    period: period || assignment.period,
    cutoff_time: assignment.cutoff_time || '06:30',
    completed_count: completedCount,
    incomplete_count: incompleteCount,
    unsubmitted_count: unsubmittedCount,
    missing_students: missingStudentNames,
    incomplete_students: incompleteStudentNames,
    recipients,
    message: `🔒 [CHỐT SỔ ${dayLabel.toUpperCase()} • TIẾT ${
      assignment.periods_merged || assignment.period
    } - MÔN ${subjectName.toUpperCase()}] Đã khóa sổ lúc ${
      assignment.cutoff_time || '06:30'
    } (Trước tiết học 30 phút). Tổng kết lớp (${totalStudents} HS): 🟢 Đã hoàn thành: ${completedCount} HS | 🟡 Nộp thiếu mục: ${incompleteCount} HS | 🔴 Chưa nộp: ${unsubmittedCount} HS.`,
    created_at: new Date().toISOString()
  };

  db.notification_logs.unshift(notificationRecord);
  saveDb(db);

  if (io) {
    io.emit('cutoff_notification', notificationRecord);
    io.emit('db_reset', db);
  }

  return notificationRecord;
}

