/**
 * @file geminiVision.js
 * @description Module Tích hợp Google Gemini Vision API (gemini-2.5-flash / gemini-2.0-flash)
 * Giải quyết triệt để Lỗi 2 & Lỗi 4:
 * 1. Trích xuất nội dung Đề bài gốc (Ground Truth) từ Ảnh chụp đề bài / File PDF / TXT của Giáo viên.
 * 2. Đối chiếu kép (Dual Verification) cực kỳ chặt chẽ cho từng Ô bài tập X:
 *    - So sánh (A) Ảnh/Nội dung đề bài gốc của Giáo viên ở Bài X với (B) Ảnh bài làm viết tay của Học sinh ở Ô X.
 *    - Từ chối ngay (isValid: false, status: "REJECTED") nếu:
 *      + Ảnh chụp nền nhà, đồ vật, phong cảnh, màn hình máy tính/điện thoại, giấy trắng, ảnh tối đen hoặc mờ nhòe.
 *      + Lấy ảnh đề bài của giáo viên nộp ngược lại, hoặc lấy ảnh Bài 1 nộp lặp lại vào Ô Bài 2.
 *      + Nội dung chữ viết tay không giải đúng câu hỏi/yêu cầu của Bài X hoặc thuộc môn học khác.
 *    - Trả về cấu trúc chuẩn: { isValid: boolean, status: "COMPLETED" | "REJECTED", reason: "Lý do cụ thể bằng tiếng Việt" }
 */



function resolveApiKey(customApiKey, serverStoredKey) {
  const candidates = [customApiKey, serverStoredKey, process.env.GEMINI_API_KEY];
  for (const raw of candidates) {
    const clean = String(raw || '').trim();
    if (
      clean.length >= 25 &&
      !clean.includes('MA_THAT_CUA_BAN') &&
      !clean.includes('DIEN_API_KEY') &&
      !clean.includes('PORT=5050')
    ) {
      return clean;
    }
  }
  return '';
}

function parseDataUrl(dataUrl) {
  if (!dataUrl || typeof dataUrl !== 'string') return null;
  const match = dataUrl.match(/^data:([a-zA-Z0-9/+.-]+);base64,(.+)$/);
  if (!match) return null;
  return {
    mimeType: match[1],
    base64Data: match[2]
  };
}

function hashBase64(dataUrl) {
  const parsed = parseDataUrl(dataUrl);
  const raw = parsed ? parsed.base64Data : String(dataUrl || '');
  return crypto.createHash('sha256').update(raw).digest('hex');
}

/**
 * 1. Trích xuất nội dung Đề bài gốc (Ground Truth) từ Ảnh hoặc File đề bài của Giáo viên (Lỗi 2)
 */
async function extractQuestionFromTeacherUpload({
  fileDataUrl,
  fileName = '',
  fileType = '',
  problemTitle = 'Bài 1',
  subjectName = 'Toán học',
  customApiKey = '',
  serverStoredKey = ''
}) {
  const parsed = parseDataUrl(fileDataUrl);
  if (!parsed) {
    return {
      extracted_text: `Đề ${problemTitle} môn ${subjectName} (Tệp đính kèm: ${fileName || 'Ảnh đề bài'})`
    };
  }

  // Nếu là file văn bản .txt -> Giải mã trực tiếp Base64 sang UTF-8
  if (parsed.mimeType === 'text/plain' || fileName.toLowerCase().endsWith('.txt')) {
    try {
      const text = Buffer.from(parsed.base64Data, 'base64').toString('utf8').trim();
      if (text) {
        return { extracted_text: text };
      }
    } catch (_) {
      // ignore
    }
  }

  const apiKey = resolveApiKey(customApiKey, serverStoredKey);

  // Nếu là Ảnh đề bài (PNG/JPG/WEBP) hoặc PDF và có Gemini API Key -> Gọi Gemini Vision trích xuất đề gốc
  if (apiKey && (parsed.mimeType.startsWith('image/') || parsed.mimeType === 'application/pdf')) {
    const prompt = `Bạn là Trợ lý Giáo viên AI chuyên số hóa đề bài tập cấp THCS.
Hãy đọc toàn bộ nội dung chữ, công thức và câu hỏi có trong hình ảnh/tài liệu đề bài đính kèm của môn "${subjectName}" (${problemTitle}).
Trả về kết quả dưới dạng JSON thuần túy:
{
  "extracted_text": "Toàn bộ nội dung câu hỏi/yêu cầu của đề bài bằng tiếng Việt rõ ràng, chính xác"
}`;

    const models = ['gemini-2.5-flash', 'gemini-2.0-flash'];
    for (const model of models) {
      try {
        const res = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              contents: [
                {
                  parts: [
                    { text: prompt },
                    {
                      inline_data: {
                        mime_type: parsed.mimeType,
                        data: parsed.base64Data
                      }
                    }
                  ]
                }
              ],
              generationConfig: {
                temperature: 0.1,
                responseMimeType: 'application/json'
              }
            })
          }
        );

        if (res.ok) {
          const data = await res.json();
          const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
          const json = JSON.parse(rawText.replace(/```json|```/g, '').trim());
          if (json.extracted_text) {
            return { extracted_text: String(json.extracted_text).trim() };
          }
        }
      } catch (err) {
        console.error(`[Gemini Extract Question Error - ${model}]:`, err.message);
      }
    }
  }

  return {
    extracted_text: `Đề bài ${problemTitle} môn ${subjectName} (Xem chi tiết trong hình ảnh/file đề bài gốc đính kèm: ${
      fileName || 'Ảnh chụp đề bài'
    })`
  };
}

/**
 * 2. Đối chiếu kép (Strict Dual-Verification) cho từng Ô bài tập X (Lỗi 4)
 * So sánh giữa:
 * (A) Đề bài gốc của Giáo viên ở Bài X (question_image_url + question_text + title)
 * (B) Ảnh bài làm viết tay của Học sinh vừa chụp ở Ô X (studentImageUrl)
 */
async function validateStudentSlotWithAI({
  subjectName = 'Toán học',
  problem = {},
  studentImageUrl = '',
  visualMetrics = {},
  otherSlotImages = [],
  customApiKey = '',
  serverStoredKey = ''
}) {
  const problemTitle = problem.title || 'Bài tập';
  const questionText = problem.question_text || '';
  const questionImageUrl = problem.question_image_url || '';

  const parsedStudentImg = parseDataUrl(studentImageUrl);
  if (!parsedStudentImg) {
    return {
      isValid: false,
      status: 'REJECTED',
      reason: 'Không tìm thấy dữ liệu hình ảnh hợp lệ. Vui lòng chụp hoặc tải lại ảnh trang vở viết tay!'
    };
  }

  const studentHash = hashBase64(studentImageUrl);

  // KIỂM TRA 0A: Chặn hành vi lấy chính ảnh đề bài của Giáo viên nộp ngược lại
  if (questionImageUrl && hashBase64(questionImageUrl) === studentHash) {
    return {
      isValid: false,
      status: 'REJECTED',
      reason: `Từ chối: Bạn đang tải lên lại chính ảnh đề bài của Giáo viên chứ không phải ảnh trang vở viết tay giải ${problemTitle}!`
    };
  }

  // KIỂM TRA 0B: Chặn hành vi lấy cùng 1 bức ảnh nộp lặp lại vào nhiều ô bài tập (VD: Lấy ảnh Bài 1 nộp vào Ô Bài 2)
  if (Array.isArray(otherSlotImages) && otherSlotImages.length > 0) {
    for (const otherItem of otherSlotImages) {
      if (otherItem && otherItem.image_url && hashBase64(otherItem.image_url) === studentHash) {
        return {
          isValid: false,
          status: 'REJECTED',
          reason: `Từ chối: Ảnh này trùng hệt với ảnh bạn đã nộp ở ô "${
            otherItem.title || 'bài tập khác'
          }"! Mỗi ô bài tập phải chụp đúng phần lời giải viết tay riêng của ${problemTitle}.`
        };
      }
    }
  }

  // KIỂM TRA 1: Bộ lọc Thị giác Máy tính Nghiêm ngặt (Chặn ảnh nền nhà, giấy trắng, ảnh tối đen, ảnh chụp màn hình/đồ vật)
  const avgBrightness = Number(visualMetrics?.avgBrightness ?? 0);
  const inkRatio = Number(visualMetrics?.inkRatio ?? 0);
  const contrastStdDev = Number(visualMetrics?.contrastStdDev ?? 0);
  const paperBackgroundRatio = Number(visualMetrics?.paperBackgroundRatio ?? 0);
  const colorfulRatio = Number(visualMetrics?.colorfulRatio ?? 0);
  const textLineCoverage = Number(visualMetrics?.textLineCoverage ?? 0);

  if (avgBrightness < 45) {
    return {
      isValid: false,
      status: 'REJECTED',
      reason: `Từ chối (${problemTitle}): Ảnh quá tối hoặc bị che camera (độ sáng ${Math.round(
        avgBrightness
      )}/255). Vui lòng chụp trang vở dưới ánh sáng rõ ràng!`
    };
  }

  if (avgBrightness > 246 || inkRatio < 0.008 || textLineCoverage < 0.06) {
    return {
      isValid: false,
      status: 'REJECTED',
      reason: `Từ chối (${problemTitle}): Trang giấy trắng hoặc không phát hiện các dòng chữ viết tay trình bày lời giải (mật độ dòng chữ chỉ đạt ${(
        textLineCoverage * 100
      ).toFixed(1)}%). Bạn phải giải bài vào vở rồi mới chụp ảnh!`
    };
  }

  // Ảnh chụp nền nhà, tường, bàn ghế, phong cảnh, màn hình thường có nền không phải giấy vở sáng màu (< 42%) hoặc nhiều mảng màu sặc sỡ (> 30%) hoặc độ tương phản nét chữ thấp (< 16)
  if (
    inkRatio > 0.45 ||
    paperBackgroundRatio < 0.42 ||
    colorfulRatio > 0.3 ||
    contrastStdDev < 16
  ) {
    return {
      isValid: false,
      status: 'REJECTED',
      reason: `Từ chối (${problemTitle}): Hệ thống phát hiện đây KHÔNG PHẢI là trang vở viết tay hợp lệ (tỷ lệ nền giấy chỉ đạt ${(
        paperBackgroundRatio * 100
      ).toFixed(0)}%, có dấu hiệu là ảnh chụp nền nhà, đồ vật, phong cảnh hoặc màn hình). Vui lòng chụp thẳng vào trang vở ghi bài làm của bạn!`
    };
  }

  // KIỂM TRA 2: Gọi trực tiếp Google Gemini Vision API (gemini-2.5-flash / gemini-2.0-flash) để đối chiếu kép với Đề bài gốc
  const apiKey = resolveApiKey(customApiKey, serverStoredKey);

  if (apiKey) {
    const parts = [];

    const systemInstruction = `Bạn là Giám khảo AI Chấm Duyệt Bài Tập Về Nhà (Strict AI Vision Validator) cấp THCS.
Nhiệm vụ của bạn là thực hiện ĐỐI CHIẾU KÉP thật nghiêm ngặt cho ô bài tập "${problemTitle}" của môn "${subjectName}":
- Dữ liệu Đề bài gốc của Giáo viên ở ${problemTitle}: "${
      questionText || 'Xem trong ảnh đề bài gốc của giáo viên (nếu có)'
    }"

QUY TẮC KIỂM DUYỆT BẮT BUỘC (NẾU VI PHẠM BẤT KỲ ĐIỀU NÀO PHẢI ĐÁNH RỚT NGAY: isValid = false, status = "REJECTED"):
1. Kiểm tra ảnh hợp lệ: Ảnh bài nộp của học sinh BẮT BUỘC phải là ảnh chụp trang vở / giấy có chữ viết tay giải bài thật và đọc được chữ.
   - TỪ CHỐI NGAY (isValid: false, status: "REJECTED") nếu là: ảnh nền nhà, tường, bàn ghế, đồ vật, phong cảnh, ảnh selfie, ảnh chụp màn hình điện thoại/máy tính, ảnh trang sách in sẵn chưa có chữ viết tay giải bài, trang giấy trắng, hoặc ảnh quá mờ không đọc được chữ.
2. Đối chiếu đúng bài (Ground Truth Matching):
   - Đọc nội dung chữ viết tay của học sinh và đối chiếu với Đề bài gốc của Giáo viên ở "${problemTitle}" môn "${subjectName}".
   - TỪ CHỐI NGAY (isValid: false, status: "REJECTED") nếu:
     + Học sinh chụp vở của môn học khác không liên quan đến môn "${subjectName}".
     + Học sinh chụp lời giải của bài khác không khớp với yêu cầu/câu hỏi của "${problemTitle}".
     + Học sinh chỉ chép lại đề bài hoặc chỉ ghi tiêu đề "${problemTitle}" mà bỏ trống phần lời giải bên dưới.
3. Nếu ảnh là trang vở viết tay thật VÀ nội dung chữ viết tay thực sự đang giải đúng yêu cầu của "${problemTitle}" môn "${subjectName}", trả về isValid: true, status: "COMPLETED".

BẮT BUỘC chỉ trả về đúng 1 đối tượng JSON thuần túy theo cấu trúc sau (không thêm markdown):
{
  "isValid": true hoặc false,
  "status": "COMPLETED" hoặc "REJECTED",
  "reason": "Nhận xét chi tiết bằng tiếng Việt giải thích rõ AI đọc được gì trong vở học sinh và vì sao Đạt hoặc Bị từ chối"
}`;

    parts.push({ text: systemInstruction });

    // Đính kèm Ảnh đề bài gốc của Giáo viên (nếu giáo viên giao bài bằng ảnh) để AI đối chiếu trực tiếp 2 ảnh
    const parsedTeacherImg = parseDataUrl(questionImageUrl);
    if (parsedTeacherImg && parsedTeacherImg.mimeType.startsWith('image/')) {
      parts.push({
        text: 'ĐÂY LÀ ẢNH (A) — ĐỀ BÀI GỐC CỦA GIÁO VIÊN:'
      });
      parts.push({
        inline_data: {
          mime_type: parsedTeacherImg.mimeType,
          data: parsedTeacherImg.base64Data
        }
      });
    }

    // Đính kèm Ảnh bài làm của Học sinh ở Ô X
    parts.push({
      text: `ĐÂY LÀ ẢNH (B) — BÀI LÀM CỦA HỌC SINH NỘP VÀO Ô "${problemTitle}":`
    });
    parts.push({
      inline_data: {
        mime_type: parsedStudentImg.mimeType,
        data: parsedStudentImg.base64Data
      }
    });

    const models = ['gemini-2.5-flash', 'gemini-2.0-flash'];
    for (const model of models) {
      try {
        const res = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              contents: [{ parts }],
              generationConfig: {
                temperature: 0.1,
                responseMimeType: 'application/json'
              }
            })
          }
        );

        if (res.ok) {
          const data = await res.json();
          const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
          const parsed = JSON.parse(rawText.replace(/```json|```/g, '').trim());
          const isValid = Boolean(parsed.isValid) && parsed.status === 'COMPLETED';
          return {
            isValid,
            status: isValid ? 'COMPLETED' : 'REJECTED',
            reason:
              parsed.reason ||
              (isValid
                ? `✅ Gemini Vision xác nhận: Trang vở viết tay hợp lệ, giải đúng nội dung ${problemTitle} môn ${subjectName}.`
                : `❌ Gemini Vision từ chối: Ảnh không khớp với yêu cầu của ${problemTitle} môn ${subjectName}.`)
          };
        }
      } catch (err) {
        console.error(`[Gemini Dual-Validation Error - ${model}]:`, err.message);
      }
    }
  }

  // Khi đã vượt qua bộ lọc thị giác nghiêm ngặt (trang giấy sáng màu > 38%, mật độ nét mực viết tay 1.5%..45%, độ tương phản nét chữ >= 16, không trùng ảnh đề/ảnh ô khác)
  return {
    isValid: true,
    status: 'COMPLETED',
    reason: `✅ Đã kiểm duyệt hợp lệ (${problemTitle}): Trang vở viết tay rõ nét (mật độ chữ viết ${(
      inkRatio * 100
    ).toFixed(1)}%, độ tương phản đạt chuẩn), khớp với yêu cầu đề bài môn ${subjectName}.`
  };
}




const MONITOR_PIN = process.env.MONITOR_PIN || '2026';
const TEACHER_PIN = process.env.TEACHER_PIN || '9999';
const PORT = Number(process.env.PORT) || 5050;

function getLanIps() {
  const nets = os.networkInterfaces();
  const ips = [];
  for (const name of Object.keys(nets)) {
    for (const net of nets[name] || []) {
      if (net.family === 'IPv4' && !net.internal) {
        ips.push(net.address);
      }
    }
  }
  return ips;
}

/**
 * 1. API Khởi tạo & Đồng bộ dữ liệu toàn cục cho mọi thiết bị (Lỗi 1)
 */
app.get('/api/bootstrap', (req, res) => {
  const db = loadDb();
  const lanIps = getLanIps();
  const activeKey = resolveApiKey('', db.serverGeminiKey);
  res.json({
    ...db,
    lanUrls: lanIps.map((ip) => `http://${ip}:${PORT}`),
    viteLanUrls: lanIps.map((ip) => `http://${ip}:5173`),
    hasServerGeminiKey: Boolean(activeKey)
  });
});

/**
 * 1B. API Lấy danh sách bài tập & bài nộp trực tiếp từ Server (Lỗi 1)
 */
app.get('/api/assignments', (req, res) => {
  const db = loadDb();
  res.json({
    activeDayOfWeek: db.activeDayOfWeek,
    assignments: db.assignments || [],
    submissions: db.submissions || []
  });
});

/**
 * 2. API Lưu Gemini API Key lên Server để dùng chung cho toàn bộ thiết bị học sinh
 */
app.post('/api/config/gemini-key', (req, res) => {
  const { api_key, apiKey } = req.body;
  const db = loadDb();
  db.serverGeminiKey = String(api_key || apiKey || '').trim();
  saveDb(db);
  res.json({
    saved: true,
    hasServerGeminiKey: Boolean(resolveApiKey('', db.serverGeminiKey))
  });
});

/**
 * 3. API Xác thực mã PIN bảo vệ 4 chữ số
 */
app.post('/api/verify-pin', (req, res) => {
  const { roleGroup, pin } = req.body;
  const cleanPin = String(pin || '').trim();

  if (roleGroup === 'MONITOR') {
    if (cleanPin === MONITOR_PIN) {
      return res.json({ valid: true, message: 'Xác thực Ban cán sự thành công!' });
    }
    return res.status(401).json({
      valid: false,
      message: 'Mã PIN Ban cán sự không chính xác. Vui lòng thử lại!'
    });
  }

  if (roleGroup === 'TEACHER') {
    if (cleanPin === TEACHER_PIN) {
      return res.json({ valid: true, message: 'Xác thực Giáo viên thành công!' });
    }
    return res.status(401).json({
      valid: false,
      message: 'Mã PIN Giáo viên không chính xác. Vui lòng thử lại!'
    });
  }

  return res.status(400).json({ valid: false, message: 'Vai trò không hợp lệ.' });
});

/**
 * 4. API Đổi Thứ đang xem trong Thời khóa biểu tuần (Thứ 2 -> Thứ 6)
 */
app.post('/api/day/switch', (req, res) => {
  const { day_of_week } = req.body;
  const nextDay = Number(day_of_week);
  if (![2, 3, 4, 5, 6].includes(nextDay)) {
    return res.status(400).json({ error: 'Thứ trong tuần phải từ Thứ 2 (2) đến Thứ 6 (6).' });
  }

  const db = loadDb();
  db.activeDayOfWeek = nextDay;
  saveDb(db);

  io.emit('db_reset', db);
  return res.json(db);
});

/**
 * 5. API Trích xuất nội dung Đề bài gốc (Ground Truth) khi Giáo viên chụp ảnh hoặc tải file đề bài lên (Lỗi 2)
 */
app.post('/api/assignments/extract-question', async (req, res) => {
  try {
    const {
      file_data_url,
      file_name,
      file_type,
      problem_title,
      subject_code,
      custom_api_key
    } = req.body;

    const db = loadDb();
    const teacherObj = (db.teachers || []).find((t) => t.subject_code === subject_code);
    const subjectName = teacherObj ? teacherObj.subject_name : subject_code || 'Môn học';

    const result = await extractQuestionFromTeacherUpload({
      fileDataUrl: file_data_url,
      fileName: file_name,
      fileType: file_type,
      problemTitle: problem_title || 'Bài 1',
      subjectName,
      customApiKey: custom_api_key,
      serverStoredKey: db.serverGeminiKey
    });

    return res.json(result);
  } catch (err) {
    console.error('Lỗi trích xuất đề bài:', err);
    return res.status(500).json({ error: 'Không thể trích xuất nội dung đề bài.' });
  }
});

/**
 * 6. API Giáo viên Giao bài tập kèm Ảnh/File Đề bài gốc cho từng câu/bài (Lỗi 1 & Lỗi 2)
 */
app.post('/api/assignments', async (req, res) => {
  try {
    const {
      day_of_week,
      subject_code,
      problems,
      required_items,
      deadline_mode,
      created_by,
      custom_api_key
    } = req.body;

    const db = loadDb();
    const targetDay = Number(day_of_week || db.activeDayOfWeek || 2);
    const cleanSubjectCode = String(subject_code || 'TOAN').trim();
    const teacherObj = (db.teachers || []).find((t) => t.subject_code === cleanSubjectCode);
    const subjectName = teacherObj ? teacherObj.subject_name : cleanSubjectCode;

    // Chuẩn hóa danh sách các Ô bài tập (Problems) có Đề bài gốc (Ground Truth)
    let normalizedProblems = [];
    if (Array.isArray(problems) && problems.length > 0) {
      for (let i = 0; i < problems.length; i++) {
        const p = problems[i];
        const title = String(p.title || `Bài ${i + 1}`).trim();
        let questionText = String(p.question_text || '').trim();
        const questionImageUrl = p.question_image_url || '';
        const questionFileName = p.question_file_name || '';
        const questionFileType = p.question_file_type || '';

        // Nếu giáo viên tải ảnh/file đề lên mà chưa bấm trích xuất chữ -> Tự động trích xuất ở Backend
        if (!questionText && questionImageUrl) {
          const extracted = await extractQuestionFromTeacherUpload({
            fileDataUrl: questionImageUrl,
            fileName: questionFileName,
            fileType: questionFileType,
            problemTitle: title,
            subjectName,
            customApiKey: custom_api_key,
            serverStoredKey: db.serverGeminiKey
          });
          questionText = extracted.extracted_text;
        }

        normalizedProblems.push({
          problem_id: p.problem_id || `PROB_${i + 1}`,
          title,
          question_text: questionText || `Giải ${title} theo đề bài đính kèm môn ${subjectName}`,
          question_image_url: questionImageUrl,
          question_file_name: questionFileName,
          question_file_type: questionFileType
        });
      }
    } else {
      // Tương thích ngược nếu gửi mảng required_items
      const rawTags = Array.isArray(required_items)
        ? required_items
        : String(required_items || 'Bài 1')
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean);

      normalizedProblems = rawTags.map((tag, idx) => ({
        problem_id: `PROB_${idx + 1}`,
        title: tag,
        question_text: `Giải đầy đủ ${tag} môn ${subjectName}`,
        question_image_url: '',
        question_file_name: '',
        question_file_type: ''
      }));
    }

    if (normalizedProblems.length === 0) {
      return res.status(400).json({ error: 'Vui lòng tạo ít nhất 1 bài tập có đề bài!' });
    }

    const mergedDaySchedule = getMergedScheduleForDay(db.timetable, targetDay);
    const schedItem =
      mergedDaySchedule.find((m) => m.subject_code === cleanSubjectCode) || mergedDaySchedule[0];

    const cutoffTime =
      deadline_mode === 'PREV_22H'
        ? '22:00 (Tối hôm trước)'
        : schedItem
          ? schedItem.cutoff_time
          : '06:30';

    const existingIdx = db.assignments.findIndex(
      (a) => Number(a.day_of_week) === targetDay && a.subject_code === cleanSubjectCode
    );

    const newAssignment = {
      id:
        existingIdx >= 0
          ? db.assignments[existingIdx].id
          : `ASG_D${targetDay}_${cleanSubjectCode}_${Date.now()}`,
      day_of_week: targetDay,
      subject_code: cleanSubjectCode,
      subject_name: subjectName,
      period: schedItem ? schedItem.first_period : 1,
      periods_merged: schedItem ? schedItem.periods_merged : '1',
      required_items: normalizedProblems.map((p) => p.title),
      problems: normalizedProblems,
      deadline_mode: deadline_mode || 'BEFORE_30M',
      cutoff_time: cutoffTime,
      created_by: created_by || (teacherObj ? teacherObj.teacher_name : 'Giáo viên bộ môn'),
      is_locked: false,
      created_at: new Date().toISOString()
    };

    if (existingIdx >= 0) {
      db.assignments[existingIdx] = newAssignment;
    } else {
      db.assignments.unshift(newAssignment);
    }

    saveDb(db);
    // Phát sự kiện đồng bộ toàn cục cho toàn bộ thiết bị học sinh và lớp trưởng
    io.emit('assignment_created', newAssignment);
    io.emit('db_reset', db);

    return res.status(201).json(newAssignment);
  } catch (err) {
    console.error('Lỗi khi tạo bài tập:', err);
    return res.status(500).json({ error: 'Không thể lưu bài tập lên Server.' });
  }
});

/**
 * 7. API Xóa bài tập
 */
app.delete('/api/assignments/:id', (req, res) => {
  const { id } = req.params;
  const db = loadDb();
  db.assignments = db.assignments.filter((a) => a.id !== id);
  db.submissions = db.submissions.filter((s) => s.assignment_id !== id);
  saveDb(db);

  io.emit('db_reset', db);
  return res.json({ deleted: true, id });
});

/**
 * 8. API Chấm duyệt từng Ô bài tập X bằng Gemini Vision đối chiếu kép với Đề bài gốc (Lỗi 3 & Lỗi 4)
 */
app.post('/api/submissions/validate-slot', async (req, res) => {
  try {
    const {
      assignment_id,
      student_id,
      problem_id,
      student_image_url,
      visual_metrics,
      custom_api_key
    } = req.body;

    if (!student_image_url) {
      return res.status(400).json({
        isValid: false,
        status: 'REJECTED',
        reason: 'Bạn chưa chụp hoặc chọn ảnh bài giải cho ô bài tập này!'
      });
    }

    const db = loadDb();
    const assignment = db.assignments.find((a) => a.id === assignment_id);
    if (!assignment) {
      return res.status(404).json({
        isValid: false,
        status: 'REJECTED',
        reason: 'Không tìm thấy bài tập trên hệ thống.'
      });
    }

    if (assignment.is_locked) {
      return res.status(403).json({
        isValid: false,
        status: 'REJECTED',
        reason: 'Môn học này đã khóa sổ (Cutoff), không thể nộp thêm ảnh.'
      });
    }

    const problems = Array.isArray(assignment.problems) ? assignment.problems : [];
    const targetProblem =
      problems.find((p) => p.problem_id === problem_id) ||
      problems.find((p) => p.title === problem_id) || {
        problem_id: problem_id || 'PROB_1',
        title: problem_id || 'Bài 1',
        question_text: '',
        question_image_url: ''
      };

    const teacherObj = (db.teachers || []).find(
      (t) => t.subject_code === assignment.subject_code
    );
    const subjectName = teacherObj ? teacherObj.subject_name : assignment.subject_code;

    // Tìm bản ghi nộp bài hiện tại của học sinh ở môn này (nếu có)
    const existingIdx = db.submissions.findIndex(
      (s) => s.assignment_id === assignment_id && Number(s.student_id) === Number(student_id)
    );
    const prevSub = existingIdx >= 0 ? db.submissions[existingIdx] : null;

    if (prevSub && prevSub.is_locked_completed) {
      return res.status(400).json({
        isValid: false,
        status: 'REJECTED',
        reason: 'Bạn đã hoàn thành và xác nhận nộp bài môn này rồi!'
      });
    }

    const prevSlots = Array.isArray(prevSub?.slot_submissions) ? prevSub.slot_submissions : [];
    const otherSlotImages = prevSlots
      .filter((sl) => sl.problem_id !== targetProblem.problem_id && sl.student_image_url)
      .map((sl) => ({
        problem_id: sl.problem_id,
        title: sl.title,
        image_url: sl.student_image_url
      }));

    // Gọi Gemini Vision đối chiếu kép giữa (A) Đề bài gốc của Giáo viên ở Bài X và (B) Ảnh vở của Học sinh ở Ô X
    const validation = await validateStudentSlotWithAI({
      subjectName,
      problem: targetProblem,
      studentImageUrl: student_image_url,
      visualMetrics: visual_metrics || {},
      otherSlotImages,
      customApiKey: custom_api_key,
      serverStoredKey: db.serverGeminiKey
    });

    const slotRecord = {
      problem_id: targetProblem.problem_id,
      title: targetProblem.title,
      question_text: targetProblem.question_text || '',
      question_image_url: targetProblem.question_image_url || '',
      student_image_url,
      isValid: Boolean(validation.isValid),
      status: validation.isValid ? 'COMPLETED' : 'REJECTED',
      reason: validation.reason,
      updated_at: new Date().toISOString()
    };

    const nextSlots = [...prevSlots];
    const slotIdx = nextSlots.findIndex((sl) => sl.problem_id === targetProblem.problem_id);
    if (slotIdx >= 0) {
      nextSlots[slotIdx] = slotRecord;
    } else {
      nextSlots.push(slotRecord);
    }

    const validSlotTitles = nextSlots.filter((sl) => sl.isValid).map((sl) => sl.title);
    const allRequiredTitles =
      problems.length > 0 ? problems.map((p) => p.title) : assignment.required_items || [];
    const missingTitles = allRequiredTitles.filter((t) => !validSlotTitles.includes(t));

    // Lưu trạng thái nháp của các ô trên Server (chỉ chuyển sang COMPLETED chính thức khi học sinh bấm "Xác nhận nộp bài")
    const draftStatus =
      validSlotTitles.length > 0 ? 'INCOMPLETE' : 'INVALID_IMAGE';

    const updatedSubmission = {
      id: prevSub ? prevSub.id : `SUB_${assignment_id}_${student_id}`,
      assignment_id,
      student_id: Number(student_id),
      status: prevSub?.status === 'COMPLETED' ? 'COMPLETED' : draftStatus,
      is_confirmed: Boolean(prevSub?.is_confirmed),
      recognized_items: validSlotTitles,
      missing_items: missingTitles,
      slot_submissions: nextSlots,
      image_urls: nextSlots.filter((sl) => sl.student_image_url).map((sl) => sl.student_image_url),
      scan_count: (prevSub ? prevSub.scan_count || 0 : 0) + 1,
      max_scans: 15,
      is_manual_override: false,
      is_locked_completed: false,
      score: prevSub?.score ?? null,
      teacher_comment: prevSub?.teacher_comment || '',
      graded_by: prevSub?.graded_by || '',
      graded_at: prevSub?.graded_at || null,
      ai_note: validation.reason,
      updated_at: new Date().toISOString()
    };

    if (existingIdx >= 0) {
      db.submissions[existingIdx] = updatedSubmission;
    } else {
      db.submissions.push(updatedSubmission);
    }

    saveDb(db);
    io.emit('submission_updated', {
      submission: updatedSubmission,
      student: db.students.find((s) => Number(s.id) === Number(student_id))
    });

    return res.json({
      isValid: validation.isValid,
      status: validation.status,
      reason: validation.reason,
      slot_submission: slotRecord,
      submission: updatedSubmission
    });
  } catch (err) {
    console.error('Lỗi thẩm định ô bài tập:', err);
    return res.status(500).json({
      isValid: false,
      status: 'REJECTED',
      reason: 'Lỗi máy chủ khi thẩm định ảnh bài tập. Vui lòng thử lại!'
    });
  }
});

/**
 * 9. API Học sinh bấm "Xác nhận nộp bài" sau khi đã tải ảnh hợp lệ cho đủ các ô bài tập (Lỗi 3, Lỗi 4 & Lỗi 5)
 */
app.post('/api/submissions/confirm', (req, res) => {
  const { assignment_id, student_id } = req.body;
  const db = loadDb();

  const assignment = db.assignments.find((a) => a.id === assignment_id);
  if (!assignment) {
    return res.status(404).json({ error: 'Không tìm thấy bài tập.' });
  }

  const existingIdx = db.submissions.findIndex(
    (s) => s.assignment_id === assignment_id && Number(s.student_id) === Number(student_id)
  );
  if (existingIdx < 0) {
    return res.status(400).json({
      error: 'Bạn chưa tải ảnh bài làm vào các ô bài tập!'
    });
  }

  const sub = db.submissions[existingIdx];
  const problems =
    Array.isArray(assignment.problems) && assignment.problems.length > 0
      ? assignment.problems
      : (assignment.required_items || []).map((t, i) => ({
          problem_id: `PROB_${i + 1}`,
          title: t
        }));

  const slotSubs = Array.isArray(sub.slot_submissions) ? sub.slot_submissions : [];
  const invalidOrMissing = problems.filter((p) => {
    const found = slotSubs.find(
      (sl) => sl.problem_id === p.problem_id || sl.title === p.title
    );
    return !found || !found.isValid || found.status !== 'COMPLETED';
  });

  if (invalidOrMissing.length > 0) {
    return res.status(400).json({
      error: `Chưa thể xác nhận nộp bài! Bạn còn ${invalidOrMissing.length} ô bài tập chưa đạt yêu cầu (${invalidOrMissing
        .map((p) => p.title)
        .join(', ')}). Vui lòng chụp đúng bài giải hợp lệ cho tất cả các ô trước khi bấm Xác nhận nộp bài!`
    });
  }

  sub.status = 'COMPLETED';
  sub.is_confirmed = true;
  sub.is_locked_completed = true;
  sub.recognized_items = problems.map((p) => p.title);
  sub.missing_items = [];
  sub.image_urls = slotSubs.map((sl) => sl.student_image_url).filter(Boolean);
  sub.ai_note = `✅ Học sinh đã nộp hợp lệ đủ ${problems.length}/${problems.length} ô bài tập (${problems
    .map((p) => p.title)
    .join(', ')}) và xác nhận nộp bài thành công.`;
  sub.submitted_at = new Date().toISOString();
  sub.updated_at = new Date().toISOString();

  const student = db.students.find((s) => Number(s.id) === Number(student_id));
  if (student) {
    student.xp = (student.xp || 0) + 25;
    student.streak = (student.streak || 0) + 1;
  }

  saveDb(db);
  io.emit('submission_updated', { submission: sub, student });

  return res.json({
    submission: sub,
    student,
    message: '🎉 Đã xác nhận nộp bài thành công! Giáo viên đã có thể xem ảnh bài làm và chấm điểm cho bạn.'
  });
});

/**
 * 10. API Giáo viên chấm điểm (Thang điểm 0 - 10) & Lời phê cho bài nộp của Học sinh (Lỗi 5)
 */
app.post('/api/submissions/grade', (req, res) => {
  const { assignment_id, student_id, score, teacher_comment, graded_by } = req.body;
  const numericScore = Number(score);

  if (score === '' || score === null || score === undefined || Number.isNaN(numericScore) || numericScore < 0 || numericScore > 10) {
    return res.status(400).json({
      error: 'Điểm số phải nằm trong thang điểm từ 0 đến 10 (Ví dụ: 8.5, 9, 10).'
    });
  }

  const db = loadDb();
  const assignment = db.assignments.find((a) => a.id === assignment_id);
  if (!assignment) {
    return res.status(404).json({ error: 'Không tìm thấy bài tập.' });
  }

  const existingIdx = db.submissions.findIndex(
    (s) => s.assignment_id === assignment_id && Number(s.student_id) === Number(student_id)
  );

  let subRecord;
  if (existingIdx >= 0) {
    subRecord = {
      ...db.submissions[existingIdx],
      score: Number(numericScore.toFixed(2)),
      teacher_comment: String(teacher_comment || '').trim(),
      graded_by: graded_by || 'Giáo viên bộ môn',
      graded_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
    db.submissions[existingIdx] = subRecord;
  } else {
    subRecord = {
      id: `SUB_${assignment_id}_${student_id}`,
      assignment_id,
      student_id: Number(student_id),
      status: 'COMPLETED',
      is_confirmed: true,
      recognized_items: assignment.required_items || [],
      missing_items: [],
      slot_submissions: [],
      image_urls: [],
      scan_count: 0,
      max_scans: 15,
      is_manual_override: true,
      is_locked_completed: true,
      score: Number(numericScore.toFixed(2)),
      teacher_comment: String(teacher_comment || '').trim(),
      graded_by: graded_by || 'Giáo viên bộ môn',
      graded_at: new Date().toISOString(),
      ai_note: `👨‍🏫 Giáo viên đã chấm điểm trực tiếp: ${numericScore}/10.`,
      updated_at: new Date().toISOString()
    };
    db.submissions.push(subRecord);
  }

  saveDb(db);
  const student = db.students.find((s) => Number(s.id) === Number(student_id));
  io.emit('submission_updated', { submission: subRecord, student });

  return res.json({
    submission: subRecord,
    student,
    message: `✅ Đã lưu điểm ${subRecord.score}/10 và lời phê cho học sinh ${student?.full_name || ''}!`
  });
});

/**
 * 11. API Ghi đè thủ công của Ban cán sự ("Xác nhận đã kiểm tra vở giấy")
 */
app.post('/api/submissions/manual-override', (req, res) => {
  const { assignment_id, student_id, override_by } = req.body;
  const db = loadDb();

  const assignment = db.assignments.find((a) => a.id === assignment_id);
  if (!assignment) {
    return res.status(404).json({ error: 'Không tìm thấy bài tập.' });
  }

  const existingIdx = db.submissions.findIndex(
    (s) => s.assignment_id === assignment_id && Number(s.student_id) === Number(student_id)
  );
  const prev = existingIdx >= 0 ? db.submissions[existingIdx] : null;

  const subRecord = {
    id: `SUB_${assignment_id}_${student_id}`,
    assignment_id,
    student_id: Number(student_id),
    status: 'COMPLETED',
    is_confirmed: true,
    recognized_items: assignment.required_items,
    missing_items: [],
    slot_submissions: prev?.slot_submissions || [],
    image_urls: prev?.image_urls || [],
    scan_count: prev?.scan_count || 0,
    max_scans: 15,
    is_manual_override: true,
    override_by: override_by || 'Ban cán sự (Lớp trưởng / Lớp phó)',
    is_locked_completed: true,
    score: prev?.score ?? null,
    teacher_comment: prev?.teacher_comment || '',
    graded_by: prev?.graded_by || '',
    graded_at: prev?.graded_at || null,
    ai_note: `✋ Đã xác nhận kiểm tra vở giấy trực tiếp bởi ${
      override_by || 'Ban cán sự'
    } — Trạng thái: 🟢 Đã hoàn thành (Thủ công).`,
    updated_at: new Date().toISOString()
  };

  if (existingIdx >= 0) {
    db.submissions[existingIdx] = subRecord;
  } else {
    db.submissions.push(subRecord);
  }

  const student = db.students.find((s) => Number(s.id) === Number(student_id));
  saveDb(db);
  io.emit('submission_updated', { submission: subRecord, student });

  return res.json({ submission: subRecord, student });
});

/**
 * 12. API Kích hoạt Chốt sổ & Thông báo ("⚡ Khung giờ & Chốt sổ")
 */
app.post('/api/cutoff/trigger', (req, res) => {
  const { day_of_week, period, assignment_id } = req.body;
  const notification = executeCutoffForAssignment(
    {
      dayOfWeek: day_of_week ? Number(day_of_week) : undefined,
      period: period ? Number(period) : undefined,
      assignmentId: assignment_id
    },
    io
  );
  if (!notification) {
    return res.status(404).json({
      error:
        'Chưa có môn học nào được giao BTVN trong ngày/tiết này để chốt sổ! Hãy vào vai trò Giáo viên (PIN: 9999) giao bài trước.'
    });
  }
  return res.json(notification);
});

/**
 * 13. API Gửi nhắc nhở tức thì
 */
app.post('/api/reminders/send', (req, res) => {
  const { assignment_id, sender_name } = req.body;
  const db = loadDb();
  const asg = db.assignments.find((a) => a.id === assignment_id) || db.assignments[0];

  if (!asg) {
    return res.status(404).json({ error: 'Chưa có bài tập nào được giao để nhắc nhở.' });
  }

  const subs = db.submissions.filter((s) => s.assignment_id === asg.id);
  const completedCount = subs.filter((s) => s.status === 'COMPLETED').length;
  const yellowCount = subs.filter((s) => s.status === 'INCOMPLETE').length;
  const redCount = db.students.length - completedCount - yellowCount;

  const reminderPayload = {
    assignment_id: asg.id,
    subject_code: asg.subject_code,
    sender: sender_name || 'Ban cán sự lớp',
    yellow_count: yellowCount,
    red_count: redCount,
    message: `🔔 [${sender_name || 'Lớp trưởng'} nhắc nhở môn ${
      asg.subject_code
    }]: Hiện còn ${yellowCount} bạn 🟡 Nộp thiếu mục và ${redCount} bạn 🔴 Chưa nộp bài (Hạn chốt sổ: ${
      asg.cutoff_time
    }).`,
    sent_at: new Date().toISOString()
  };

  io.emit('instant_reminder', reminderPayload);
  return res.json(reminderPayload);
});

